insert into public.compliance_docs (id, name, doc_type, number, issuer, issue_date, expiry_date, status, key_facts, summary, _src, _seed, data) values ('cd-profile-2026', 'LANDSCAPERS INC - Professional Estate Landscaping & Grounds Maintenance (Introduction | Estate & Office Park Landscaping Services)', 'profile', null, 'Landscapers Inc', null, null, 'unknown', '{"id":"PROFILE-2026","title":"LANDSCAPERS INC - Professional Estate Landscaping & Grounds Maintenance (Introduction | Estate & Office Park Landscaping Services)","pdf_title":"Landscapers INC - Professional Contract Submission","author":"Anthony Guruvadu","created":"2026-05-20 22:14","pages":15,"location":"Durban, KwaZulu-Natal","registration":"2024/786147/07","contact":"069 131 5387","public_liability_cover":"R1,000,000","sections":["1 | Executive Summary","2 | Company Profile","3 | Method Statement","4 | Health, Safety & Risk Management Compliance","5 | Operational Equipment Inventory"],"target_market":"Residential estates, townhouse complexes, sectional title developments, office parks, commercial properties in Durban and surrounds (also residential, commercial and industrial properties)","mission":"At Landscapers Inc, our mission is to create sustainable, vibrant, and functional outdoor spaces that harmonize beauty with environmental responsibility. We aim to transform every landscape into a living masterpiece that enhances property value, supports ecological balance, and brings joy to our clients.","commitment":"Landscapers INC is committed to maintaining landscaped areas to a consistently high standard, ensuring safety, reliability, and professional service delivery at all times.","work_frequency":"Weekly (standard estates) / Bi-Weekly (office parks); seasonal adjustments during high-growth periods; work during approved estate working hours","minimum_site_deployment":{"total_field_staff":4,"supervisors":1,"note":"Decided per site - this is a minimum number of staff to be deployed"}}'::jsonb, 'Company profile / contract submission document.', 'x/Company Documents-20260923T091637Z-1-001/Company Documents/LandscapersINC Business Profile.pdf | pages 1-15', true, '{}'::jsonb) on conflict (id) do update set name = excluded.name, doc_type = excluded.doc_type, number = excluded.number, issuer = excluded.issuer, issue_date = excluded.issue_date, expiry_date = excluded.expiry_date, status = excluded.status, key_facts = excluded.key_facts, summary = excluded.summary, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.compliance_docs._seed and public.compliance_docs.updated_by is not distinct from public.compliance_docs.created_by;
