insert into public.crews (id, name, members, color, capacity_per_day, active, leader_id, notes, _src, _seed, data) values ('crew-1', 'Crew 1 — Sipho, Bengu, Sinoko', '["emp-mzimela","emp-bengu","emp-mngoma"]'::jsonb, '#1f7440', 6, true, null, 'Built from the September 2026 schedule, where these names work together most often (108 schedule rows include them). No team leader / driver is recorded — set one so dispatch can assign a vehicle.', 'knowledge/schedule_ops_registers.json crew_combinations', true, '{}'::jsonb) on conflict (id) do update set name = excluded.name, members = excluded.members, color = excluded.color, capacity_per_day = excluded.capacity_per_day, active = excluded.active, leader_id = excluded.leader_id, notes = excluded.notes, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.crews._seed and public.crews.updated_by is not distinct from public.crews.created_by;
