insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-financials-d-disc-020-425fca', 'DISC-020', 'Income statements', 'low', 'Empty formatted table', 'Evidence: Table_1 ("Aug-style") defined on Aug!D3:E9 but those cells are empty in both files (template copied from Sep "Outstanding" list?).', 'open', null, 'x/LSI INCOME STATEMENT (1).xlsx | xl/tables/table1.xml ; x/LSI_INCOME_STATEMENT.xlsx | xl/tables/table1.xml', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-financials-d-disc-021-782f70', 'DISC-021', 'Income statements', 'low', 'Costing items without value', 'Evidence: CHAINSAW C15="N/A", SPADE DIGGINGS C18="FREE", TRAFFIC CONES C30 blank (qty 6). SUM ignores them; total 462633.58 recomputed and matches.', 'open', null, 'x/LSI INCOME STATEMENT (1).xlsx | Costing!A15:C15, A18:C18, A30:C30, C51 ; x/LSI_INCOME_STATEMENT.xlsx | same cells', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-financials-d-disc-022-81457e', 'DISC-022', 'Income statements', 'low', 'Mixed VAT basis in Costing values (suspected)', 'Evidence: Several values are exactly a round price / 1.15 (VAT-exclusive): FS291 BRUSHCUTTER 15791.3 (x1.15 = 18160), FIXED NYLON HEAD 347.83 (=400), SILLY MANUEL POLE SAW 5217.39 (=6000), SECATUERS 156.52 (=180), HEDGER SHEAR 307.83 (=354), RAKE STEEL 113.04 (=130), 5LT FUEL CANISTER 373.04 (=429), HACK BLADE 768.7 (≈884), HAND TOOLS 2238.7 (=2574.5), LOPPING 630.43 (≈725); others are round retail (VAT-inclusive-looking) prices such as LAWNMOWER 6995, LADDER 4899, WHEEL BARROW 499, NETTING 299.', 'open', null, 'x/LSI INCOME STATEMENT (1).xlsx | Costing!C2:C50 ; x/LSI_INCOME_STATEMENT.xlsx | Costing!C2:C50', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-financials-d-disc-023-8773b4', 'DISC-023', 'Income statements', 'low', 'Costing list is incomplete as an asset register', 'Evidence: No purchase dates, suppliers, serial numbers, registration numbers or condition; "AMOUNT" column is actually quantity; only the LAWNMOWER (6995 = May EQUIPMENT) and the vehicles/GARDEN GREEN DESIGN can be matched to a month. Monthly EQUIPMENT + PPE + PRINTING lines Jan-Sep do not reconcile line by line to the Costing list.', 'open', null, 'x/LSI INCOME STATEMENT (1).xlsx | Costing!A1:C51 ; x/LSI_INCOME_STATEMENT.xlsx | Costing!A1:C51', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-financials-d-disc-024-206bf8', 'DISC-024', 'Income statements', 'medium', 'GARDEN GREEN DESIGN R130000 unexplained', 'Evidence: Costing!A50:C50 "GARDEN GREEN DESIGN" qty 1, 130000.0 and July!A24:B24 130000.0 as an operating cost. Nature (business acquisition, client book, design contract?) not stated. Adhoc sheet also shows "Garden Design" jobs in August (3172.5 and 4726.61 profit).', 'open', null, 'x/LSI INCOME STATEMENT (1).xlsx | Costing!A50:C50, July!A24:B24, Adhoc !A24:D25 ; x/LSI_INCOME_STATEMENT.xlsx | same cells', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
