insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-invoices-apr-may-d-2-7a32d5', 'INVOIC-D03', 'Invoices Apr–May', 'medium', '"Maintenance Visit N" means the number of visits on some invoices (Brenton/Gracy/Shaun: price × N) and a visit label on others (Ruth/Shanene: price is the line total) — the new system prints quantity and unit price ex…', '"Maintenance Visit N" means the number of visits on some invoices (Brenton/Gracy/Shaun: price × N) and a visit label on others (Ruth/Shanene: price is the line total) — the new system prints quantity and unit price explicitly.', 'open', null, 'knowledge/invoices_apr_may.json discrepancies[2]', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
