insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-invoices-july-d-1-c02aa4', 'INVOIC-D02', 'Invoices July', 'medium', 'July invoices use the new "INVOICE" template with INV- numbers; HSBC 001 (Herrwood Skye Body Corporate) uses a third layout with the registration line at the top.', null, 'open', null, 'knowledge/invoices_july.json discrepancies[1]', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-invoices-july-d-2-c9e648', 'INVOIC-D03', 'Invoices July', 'medium', 'INV-035AD / INV-038AD / INV-034AD suffix "AD" = ad-hoc invoices sharing the client number of the maintenance invoice.', null, 'open', null, 'knowledge/invoices_july.json discrepancies[2]', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
