insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-invoices-june-d-invjun-d01-0e4db2', 'INVJUN-D01', 'Invoices June', 'high', 'Invoice numbers are not unique: 11 of the 13 June invoices, all dated 25/06/2026, carry the same printed number "3". The number is a per-client running count, not a company-wide sequence, so an invoice cannot be ident…', 'Invoice numbers are not unique: 11 of the 13 June invoices, all dated 25/06/2026, carry the same printed number "3". The number is a per-client running count, not a company-wide sequence, so an invoice cannot be identified by its number alone (bank references, statements, audit trail).

Evidence: Printed "Invoice Number:3" on Brenton, Divishen, Gracy, Jayen, Joash, Mervin, Ndumiso, Prabba(Praba), Ruth, Shanene, Vanishree invoices (11 incl. Divishen & Mervin whose file names say 2); "Invoice Number:2" on Kevin; "Invoice Number: LSI 201" on Amith Singh.', 'open', '{"category":"invoice_numbering"}'::jsonb, 'all 13 June 2026 invoices (x/Invoices-20260923T091654Z-1-001/Invoices/INVOICES JUNE/*.pdf) | page 1, Invoice Number line', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-invoices-june-d-invjun-d02-74f4d8', 'INVJUN-D02', 'Invoices June', 'medium', 'Divishen: file name says invoice 2 but the document prints invoice number 3. The previous (May) Divishen invoice was 001, so 2 is the expected number - the printed "3" appears to be a copy-over error from the template.', 'Evidence: File "Divishen Invoice 2.pdf"; page 1 "Invoice Number:3"; May file "Divishen Invoice 1.pdf" printed "Invoice Number:001".', 'open', '{"category":"invoice_numbering"}'::jsonb, 'x/Invoices-20260923T091654Z-1-001/Invoices/INVOICES JUNE/Divishen Invoice 2.pdf | page 1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
