insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-invoices-june-d-invjun-d04-152d84', 'INVJUN-D04', 'Invoices June', 'low', 'Kevin invoice is number 2 but no Kevin invoice number 1 exists in the April or May invoice folders.', 'Evidence: File "Kevin Invoice 2.pdf", printed "Invoice Number:2"; INVOICES APRIL and INVOICES MAY folders contain no Kevin invoice.', 'open', '{"category":"invoice_numbering"}'::jsonb, 'x/Invoices-20260923T091654Z-1-001/Invoices/INVOICES JUNE/Kevin Invoice 2.pdf | page 1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
