insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d01-b023a6', 'D01', 'People & HR', 'high', 'Renesh Gunpath start date', 'Contract clause 2 start date is handwritten "1 JULY 2021", but the contract was signed 26/06/2026, the company was registered 2024-12-11 (2024/786147/07) and payroll (financials EMP-013) only starts July 2026. Almost certainly meant 1 July 2026. Affects probation end, notice period tier and leave accrual.', 'open', null, 'x/Contracts Employees-20260923T091634Z-1-001/Contracts Employees/Renesh Gunpath.pdf | p2, p7 ; cross-ref financials EMP-013', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d02-f147f1', 'D02', 'People & HR', 'high', 'Invalid ID number on Carron Glen form (row 7, Site Manager)', 'Typed "95011529 2081" = 950115292081 (12 digits; fails SA ID format). Inserting "8" gives 9501185292081 (Anthony Samuel Guruvadu, Luhn pass). Name field blank and the photo is not in the Employee Index folder, so identity is unconfirmed. The Body Corporate holds an unusable ID for this person.', 'open', null, 'x/Carron Glen-20260923T091742Z-1-001/Carron Glen/Carron Glen Employee registration.pdf | p2 row 7', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d03-6822b0', 'D03', 'People & HR', 'medium', 'Carron Glen form completeness', 'All 7 NAME fields are blank (only photo + ID number); form year "20___" not filled; "Site Manger" misspelt (x2) plus a stray "Site Manger" below the table on p3; "Individual units" box not ticked although unit-level services are listed; ID/driver''s licence copies not attached to this PDF; office-use activation fields blank.', 'open', null, 'x/Carron Glen-20260923T091742Z-1-001/Carron Glen/Carron Glen Employee registration.pdf | p1-p3', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d04-5bbebc', 'D04', 'People & HR', 'medium', 'Staff working at Carron Glen but not registered', 'Cross-ref schedule Sep 2026: BENGU scheduled at 20 & 17 Carron Glen and CELU at 17 Carron Glen, but neither is on the 29/06/2026 registration. Carron Glen minutes of 2026-08-03 (company_compliance) also record "removal of T.Bengu from site", yet the September schedule still sends BENGU there.', 'open', null, 'x/Carron Glen-20260923T091742Z-1-001/Carron Glen/Carron Glen Employee registration.pdf | p1-p2 ; cross-ref schedule_ops_registers sites 20/17 CARRON GLEN ; company_compliance action 3.2', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d05-8fba06', 'D05', 'People & HR', 'medium', 'Renesh Gunpath job title inconsistent', 'Contract: Site Manager; Carron Glen form: "Site Manger"; medical certificate (cross-ref): OPERATIONAL MANAGER; CRM seed: Salesperson; ops register: supervisor.', 'open', null, 'x/Contracts Employees-20260923T091634Z-1-001/Contracts Employees/Renesh Gunpath.pdf | p2 ; x/Carron Glen-20260923T091742Z-1-001/Carron Glen/Carron Glen Employee registration.pdf | p2 ; cross-ref medicals MEDEMP-07, existing_crm_seed, schedule_ops_registers', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d06-066974', 'D06', 'People & HR', 'low', 'Anthony Guruvadu designation changes', 'PPE form 13/04/2026: "OPS MANAGER"; contract 26/06/2026: "GM"; medical: GENERAL MANAGER; CRM seed: "Owner / Director"; Carron Glen form names Jared Naidoo as owner. Confirm current titles and who is the owner.', 'open', null, 'x2/EX_Employees/Lutchman ex empolyee.pdf | p1 ; x/Contracts Employees-20260923T091634Z-1-001/Contracts Employees/Renesh Gunpath.pdf | p7 ; x/Carron Glen-20260923T091742Z-1-001/Carron Glen/Carron Glen Employee registration.pdf | p1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d07-be2152', 'D07', 'People & HR', 'medium', 'First Aid certificate level conflict', 'Details block: "LEVEL: 5" (US 120496, 8 credits) but body text: "FIRST AID LEVEL 2". Verify with Zabuye/SAQA which is correct.', 'open', null, 'x/Certificates-20260923T091637Z-1-001/Certificates/BMG1-A GURUVADU-FIRST AID.pdf | p1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d08-a8a492', 'D08', 'People & HR', 'low', 'Zabuye certificate formatting', 'Provider postal code 4057 on SHE Rep certificate vs 4051 on the other three; "Riverhorse vally" typo; wording "capable of Act 1993" garbled; label "Surname & Forenames" but name printed forename-first; certificates omit middle name Samuel.', 'open', null, 'x/Certificates-20260923T091637Z-1-001/Certificates/BMG-A GURUVADU-SHE REP.pdf | p1 ; x/Certificates-20260923T091637Z-1-001/Certificates/BMG1-A GURUVADU-FIREFIGHTING.pdf | p1 ; x/Certificates-20260923T091637Z-1-001/Certificates/BMG1-A GURUVADU-FIRST AID.pdf | p1 ; x/Certificates-20260923T091637Z-1-001/Certificates/BMG1-A GURUVADU -WAH.pdf | p1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d09-aceb08', 'D09', 'People & HR', 'low', 'JPJ certificate numbering / identifiers', 'JE Naidoo certificate prints subject items 9 and 10 as "1." and "2."; neither JPJ certificate carries a certificate number, issue date, NQF level, credits or expiry; the same "Membership Number: GP/AS/2026" appears on both (looks like the issuer''s SALI membership, not a learner number).', 'open', null, 'x/Certificates-20260923T091637Z-1-001/Certificates/Landscape Design & Horticulture JE Naidoo.pdf | p1 ; x/Certificates-20260923T091637Z-1-001/Certificates/Landscape Design & Horticulture AS Guruvadu.pdf | p1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d10-55112d', 'D10', 'People & HR', 'medium', 'Restraint of trade radius', 'Restraint is 24 months within a radius written as "2000" km (faint). A 2000 km radius covers practically all of South Africa and may be unenforceable; clause itself limits it to what is lawful. Confirm intended figure.', 'open', null, 'x/Contracts Employees-20260923T091634Z-1-001/Contracts Employees/Renesh Gunpath.pdf | p6 clause 17', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d11-b6ccfd', 'D11', 'People & HR', 'low', 'Contract employer details incomplete', 'Employer Registration Number left blank; employer address written as "Block 1B, Siphosethu Road Kingfisher Office Park" without street number (CIPC: 28-30 Siphosethu Road), suburb (Mount Edgecombe) or postal code (4300). Employee address "37 Stoneham Ave Phoenix" has no postal code. No witness signatures.', 'open', null, 'x/Contracts Employees-20260923T091634Z-1-001/Contracts Employees/Renesh Gunpath.pdf | p2 ; cross-ref company_compliance REG-CIPC-COR21.1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d12-3c0a5e', 'D12', 'People & HR', 'low', 'Working hours arithmetic', 'Mon-Fri 7:00am-4:00pm written as "9HOURS" (5 x 9 = 45 h/week, the BCEA ordinary-hours maximum) with no meal interval stated; the Landscaping Technician template (cross-ref) specifies a 30-minute meal interval.', 'open', null, 'x/Contracts Employees-20260923T091634Z-1-001/Contracts Employees/Renesh Gunpath.pdf | p3 clause 6 ; cross-ref company_compliance TPL-EMP-LT', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d13-c62b5a', 'D13', 'People & HR', 'medium', 'Ex-employee files', '"Ex Employee.pdf" (854,035 bytes) and "Lutchman ex empolyee.pdf" (805,018 bytes) are two different scans of the SAME signed PPE issue form - there is no exit/termination record (dates, reason, final pay, PPE return) in either. File name misspelt "empolyee".', 'open', null, 'x2/EMPLOYEES/Ex Employee.pdf | p1-p2 ; x2/EX_Employees/Lutchman ex empolyee.pdf | p1-p2', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d14-119d94', 'D14', 'People & HR', 'medium', 'Lutchman Ramsaroop not on payroll', 'PPE issued 13/04/2026 with company number 001, but no LUTCHMAN/RAMSAROOP entry exists in the Jan-Sep 2026 payroll (financials). Ex employees.xlsx says PPE returned "Partial" without listing outstanding items; 10 units were issued.', 'open', null, 'x2/EX_Employees/Lutchman ex empolyee.pdf | p1 ; cross-ref financials employees, schedule_ops_registers ex_employees', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d15-15e049', 'D15', 'People & HR', 'low', 'PPE form fill quality', '"Division | Site Name" filled with job title (Landscape Technician); "Signature of receipt" column blank on all 7 lines; item sizes not recorded; form refers to "2.40 General MATRIX of PPE" but the attached matrix is unnumbered.', 'open', null, 'x2/EX_Employees/Lutchman ex empolyee.pdf | p1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-people-hr-d-d16-6ae6ff', 'D16', 'People & HR', 'low', 'PPE matrix not tailored to landscaping', 'The attached OHASA matrix covers General Cargo, Metal/Chemical Products, Washbay, Container Depot, Stevedoring, Cold Storage, Transport and Workshop - no landscaping/garden-maintenance column (e.g. brush-cutter visor/face shield, hearing protection, sun protection). Items actually issued (sunhat, bottle, gumboots) are not in the matrix. Committee named "HSE" in one row and "SHE" in another.', 'open', null, 'x2/EX_Employees/Lutchman ex empolyee.pdf | p2', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
