insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-01-89cf79', 'D-01', 'Projects, fleet & purchases', 'high', 'Vehicle H100 buyer entity', 'MA Motors invoice INV173 (27/11/2025) is billed to "JKN GLOBAL TRADING", CK 2021/554688/07, 63 Guardbridge Gardens Stonebridge - a different entity from JKN Property Consortium (2024/786147/07), which is the eNaTIS title holder/owner from 2026-01-30. No transfer/sale document between the two entities is in the files.', 'open', null, 'x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 1 Purchase agreement.pdf | p1 ; x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 1 Logbook.pdf | p1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-02-4a2eda', 'D-02', 'Projects, fleet & purchases', 'high', 'NP200 and Garden Green bought by Jared Naidoo personally', 'NP200 agreement buyer = Jared Naidoo (ID 9902215045087); Garden Green/Splash n Grow buyer = Jared Naidoo. The NP200 is registered to JKN Property Consortium (2026-06-23) and both amounts are expensed in the company income statement (July 2026). Ownership/loan-account treatment is not documented.', 'open', null, 'x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 2 Purchase agreement.pdf | p1 ; x2/Purchases/Purchase agreemment Garden Green.pdf | p1 ; x/LSI_INCOME_STATEMENT.xlsx / x/LSI INCOME STATEMENT (1).xlsx (cross-reference via knowledge/financials.json)', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-03-e3bdde', 'D-03', 'Projects, fleet & purchases', 'medium', 'H100 cost vs ledger', 'Invoice total R167,000.00 (R165,000 vehicle + R2,000 licensing & registration) vs income statement January 2026 "H100" R168,500 (difference R1,500). Costing sheet shows R167,000 (matches). eNaTIS fees on the logbook: R138 registration + R207 licence = R345.', 'open', null, 'x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 1 Purchase agreement.pdf | p1 ; x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 1 Logbook.pdf | p1-p2 ; x/LSI_INCOME_STATEMENT.xlsx / x/LSI INCOME STATEMENT (1).xlsx (cross-reference via knowledge/financials.json)', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-04-326c21', 'D-04', 'Projects, fleet & purchases', 'medium', 'NP200 cost and timing vs ledger', 'Agreement price R64,000 on 18/06/2026 vs income statement July 2026 "NP200" R66,500 (difference R2,500; eNaTIS fees R138 + R517 = R655 do not explain it). Purchase and registration were in June but the expense sits in July.', 'open', null, 'x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 2 Purchase agreement.pdf | p1 ; x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 2 Logbook.pdf | p1-p2 ; x/LSI_INCOME_STATEMENT.xlsx / x/LSI INCOME STATEMENT (1).xlsx (cross-reference via knowledge/financials.json)', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-05-e37891', 'D-05', 'Projects, fleet & purchases', 'medium', 'Garden Green payment timing vs ledger', 'Agreement schedules R65,000 on 2/06/2026 and R65,000 on 25/06/2026, but the income statement books "GARDEN GREEN DESIGN" R130,000 in July 2026. No proofs of payment in the files. The financials group listed this R130,000 as "nature not stated" - this agreement explains it (purchase of businesses Garden Green Design & Splash n Grow as a going concern).', 'open', null, 'x2/Purchases/Purchase agreemment Garden Green.pdf | p1 ; x/LSI_INCOME_STATEMENT.xlsx / x/LSI INCOME STATEMENT (1).xlsx (cross-reference via knowledge/financials.json)', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-06-fbe156', 'D-06', 'Projects, fleet & purchases', 'medium', 'Licence renewal dates', 'H100 disc expiry on MVL1 = 2026-12-31 but Service dates sheet says RENEWAL OF LICENSE 30.11.2026; NP200 disc expiry on MVL1 = 2027-05-31 but sheet says 30.04.2027. Official eNaTIS dates should govern (sheet may be a deliberate one-month-early reminder - confirm).', 'open', null, 'x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 1 Logbook.pdf | p2 ; x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 2 Logbook.pdf | p2 ; x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Service dates.xlsx (cross-reference; owned by group schedule_ops_registers)', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-07-5c70e6', 'D-07', 'Projects, fleet & purchases', 'low', 'H100 tare weight', 'DSW form declares tare 1600KG / capacity 1.6 TON; eNaTIS tare is 1665 kg.', 'open', null, 'x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Cornubia.pdf | p1 ; x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 1 Logbook.pdf | p1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-08-b0ea30', 'D-08', 'Projects, fleet & purchases', 'medium', 'DSW form vehicle listed before company ownership', 'DSW application dated 12/12/2025 lists H100 BP75CKZN for JKN Property Consortium, while the vehicle was invoiced to JKN Global Trading (27/11/2025) and only registered to the company on 2026-01-30.', 'open', null, 'x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Cornubia.pdf | p1 ; x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 1 Logbook.pdf | p1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-09-0fa2c9', 'D-09', 'Projects, fleet & purchases', 'low', 'DSW applicant vs signatory and name spelling', 'Applicant full name written "JARED EMMANUAL NAIDOO" (ID/CIPC spelling is EMMANUEL); the form is signed by ANTHONY SAMUEL GURUVADU as MANAGER, not by the applicant. No business stamp; no DSW site ticked (Bellair vs Mt. Edgecombe) although the file is named "Cornubia".', 'open', null, 'x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Cornubia.pdf | p1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-10-594ad2', 'D-10', 'Projects, fleet & purchases', 'low', 'Postal code for 28-30 Siphosethu Road', 'CIPC COR21.1 uses 4300; eNaTIS BRNC/MVL1 use 4320.', 'open', null, 'x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Cornubia.pdf | p2 ; x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 1 Logbook.pdf | p2-p3', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-11-49276a', 'D-11', 'Projects, fleet & purchases', 'low', 'Standard Bank letter differences (same account)', '11 Dec 2025 letter: accountholder name LANDSCAPERS INC, type MYMOBIZ CURRENT ACCOUNT, branch CORNUBIA, branch code 046227 and electronic 051001. 4 Dec 2025 letter: account holder JKN PROPERTY CONSORTIUM, type CURRENT, account 0000010264092722 (zero-padded), Cornubia Service Centre, branch code 051001. Use 10264092722 / universal branch code 051001 for EFTs.', 'open', null, 'x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Cornubia.pdf | p6-p7', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-12-b7bc25', 'D-12', 'Projects, fleet & purchases', 'medium', 'Buffelsdraai pack incomplete / chronology', 'The "DSW Application Form Buffelsdraai" PDF contains no application form. The eThekwini invoice included is only pages 2-3 of 3 (page 1 with totals/date missing) and covers service up to 2026-02-28, i.e. it post-dates the 12/12/2025 consent letter and ID certification - the pack was assembled or re-submitted in/after March 2026.', 'open', null, 'x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Buffelsdraai.pdf | p1-p5', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-13-8a7a51', 'D-13', 'Projects, fleet & purchases', 'low', 'Director addresses', 'CIPC and purchase documents give Jared Naidoo''s address as 63 Guardbridge Gardens, Stonebridge, Phoenix 4068; the municipal account used for DSW is for "my property" 11 Rockbridge Avenue, Stonebridge, Phoenix.', 'open', null, 'x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Cornubia.pdf | p2 ; x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Buffelsdraai.pdf | p3-p4', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-14-7579ef', 'D-14', 'Projects, fleet & purchases', 'low', 'Municipal invoice arithmetic', 'Printed daily average 12.54 kWh/day but 1257 kWh / 93 days = 13.52 kWh/day. Sewage ISC 9.90 kl x 1.48 = 14.652 printed 14.66 (rounding). All other line amounts recompute correctly (228.46, 242.84, 471.30, 16.28, 31.58, 47.78, 79.36, 1,403.63, 1,177.34, 4,122.33). Third-party document - informational only.', 'open', null, 'x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Buffelsdraai.pdf | p4-p5', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-15-b053db', 'D-15', 'Projects, fleet & purchases', 'low', 'DSW tariff VAT rounding', 'R175,53 excl x 1.15 = R201,86; form prints R201,85.', 'open', null, 'x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Cornubia.pdf | p1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-16-1e3ad9', 'D-16', 'Projects, fleet & purchases', 'low', 'Carron Glen rehabilitation works vs quote', 'Section 9 lists 9 completed works; the quote (section 11) prices 8 lines - item 9 "Restoration and enhancement of the overall appearance of the estate" is not priced; item 7 wording differs ("clean-up" vs "site clean-up"). Quote total R24,150 recomputes correctly but is "DISCOUNTED TO R0,00" - a R24,150 give-away with no record in the income statement or CRM. The maintenance schedule table is headed "Daily Visits" but its four columns are unlabelled.', 'open', null, 'x/Carron Glen-20260923T091742Z-1-001/Carron Glen/Project plan Carron.pdf | p3, p5, p10', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-17-5875ed', 'D-17', 'Projects, fleet & purchases', 'medium', 'March 2026 payments not in company books', 'On 09/03/2026 Jared Naidoo paid R6,200 + R6,200 to JPJ Landscapers (refs "Anthony", "Jared") and R2,400 to Random Harvest (ref "landscapers Inc") = R14,800 from a Nedbank account in his name. The March 2026 income statement shows only staff R15,000, insurance R1,900, fuel R100.10 and printing R214 - none of these payments. Random Harvest balance R2,400 has no POP.', 'open', null, 'x2/Purchases/Proof_Of_Payment.pdf | p1 ; x2/Purchases/Proof_Of_Payment (1).pdf | p1 ; x2/Purchases/Proof_Of_Payment (2).pdf | p1 ; x2/Purchases/ProformaNo5904.pdf | p1 ; x/LSI_INCOME_STATEMENT.xlsx / x/LSI INCOME STATEMENT (1).xlsx (cross-reference via knowledge/financials.json)', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-18-5d9f58', 'D-18', 'Projects, fleet & purchases', 'medium', 'Garden Green seller ID fails checksum', 'Handwritten seller ID read as 7405045105089 fails the SA ID Luhn check; the handwriting is ambiguous (7406045105089 or 7405045105081 would pass). Needs a copy of the seller''s ID.', 'open', null, 'x2/Purchases/Purchase agreemment Garden Green.pdf | p1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-19-6237e3', 'D-19', 'Projects, fleet & purchases', 'medium', 'Garden Green agreement incomplete scan', 'Page 1 ends at section 3 and page 2 starts in the middle of section 8; sections 4-7 (incl. "4. ASSETS INCLUDED", faintly visible as show-through) are missing. Page 3 holds only the witness-2 lines. Witnesses not completed.', 'open', null, 'x2/Purchases/Purchase agreemment Garden Green.pdf | p1-p3', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-20-2c374e', 'D-20', 'Projects, fleet & purchases', 'medium', 'Anthony Guruvadu driving licence legibility / validity', 'Certified licence copy is too faint to read the licence number or validity dates; the valid-to date appears to be 09/11/202? - if it is 2025 the licence had expired before the 12/12/2025 DSW application. Code C1 visible.', 'open', null, 'x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Cornubia.pdf | p5', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-21-e0248d', 'D-21', 'Projects, fleet & purchases', 'low', 'Reference letters without dates/signatures', 'Pam Golding Properties letter is undated and unsigned (typed name only); Praba Callakoppen letter is undated with no signatory name/contact in the text.', 'open', null, 'x/References-20260923T091632Z-1-001/References/Reference Pam Golding Properties.pdf | p1 ; x/References-20260923T091632Z-1-001/References/Reference Praba Callakoppen.pdf | p1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-22-867529', 'D-22', 'Projects, fleet & purchases', 'low', 'MA Motors seller entity naming', 'Letterhead MA MOTORS CK 2024/349720/07; terms say vehicle remains property of MA ENTERPRISES PTY LTD; bank account name MA ENTERPRISES PTY. Client signature line blank.', 'open', null, 'x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 1 Purchase agreement.pdf | p1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-23-2629b8', 'D-23', 'Projects, fleet & purchases', 'low', 'Service sheet vs purchase chronology', 'Service sheet records NP200 "service" on 2026-06-18 at 191,222 km - the same day as the purchase agreement and before registration (2026-06-23). H100 mileage at purchase 134,352 km (27/11/2025) vs 143,475 km at 2026-08-23 service (+9,123 km). H100 next service date 2026-03-23 precedes the service date (already flagged by schedule_ops_registers).', 'open', null, 'x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 2 Purchase agreement.pdf | p1 ; x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Fleet Vehicle 1 Purchase agreement.pdf | p1 ; x/Fleet Vehicle-20260923T091632Z-1-001/Fleet Vehicle/Service dates.xlsx (cross-reference; owned by group schedule_ops_registers)', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-24-ebb600', 'D-24', 'Projects, fleet & purchases', 'low', 'SAPS certifying officer force numbers', 'The same certifying officer (R. R?mpersad, W/O) wrote the force number differently/illegibly on the three certifications (approx. 044?89?8 / 04?18?08).', 'open', null, 'x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Buffelsdraai.pdf | p2 ; x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Cornubia.pdf | p3-p4', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-projects-fleet-purchases-d-d-25-7f38ae', 'D-25', 'Projects, fleet & purchases', 'low', 'Anthony Guruvadu printed date of birth', 'Printed DOB on both ID copies is blurred (last digit of year could read 5 or 6); ID number 9501185292081 passes Luhn and encodes 1995-01-18.', 'open', null, 'x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Buffelsdraai.pdf | p2 ; x/DSW-20260923T091633Z-1-001/DSW/DSW Application Form Cornubia.pdf | p4', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
