insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-sops-toolbox-d-sop-d1-3ad8ce', 'SOP-D1', 'SOPs & toolbox talks', 'low', 'The Equipment Management SOP, Incident Reporting SOP and Job Scheduling SOP each exist as two byte-for-byte identical .docx files, one in each of two Google-Drive export folders (SOPS-20260923T091755Z-1-001 and SOPS-2…', 'The Equipment Management SOP, Incident Reporting SOP and Job Scheduling SOP each exist as two byte-for-byte identical .docx files, one in each of two Google-Drive export folders (SOPS-20260923T091755Z-1-001 and SOPS-20260923T091804Z-1-001, timestamps 9 minutes apart).

