insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-sops-toolbox-d-sop-d2-58813a', 'SOP-D2', 'SOPs & toolbox talks', 'medium', 'None of the 9 SOPs has a document code, revision/version number, issue date, effective date, or a named (as opposed to role-only) approver or signatory. This makes it impossible to know which version of a given SOP is…', 'None of the 9 SOPs has a document code, revision/version number, issue date, effective date, or a named (as opposed to role-only) approver or signatory. This makes it impossible to know which version of a given SOP is currently in force, or who last approved it.

