insert into public.data_issues (id, code, source_group, severity, title, question, status, _src, _seed, data) values ('di-strategy-roles-q-5-c60193', 'STRATE-Q06', 'Strategy & roles', 'low', 'Should the Operations Department Code of Conduct have its own employee/manager signature-acknowledgement block added (to match the Sales Code of Conduct), and are there existing signed copies on file for current staff?', 'Should the Operations Department Code of Conduct have its own employee/manager signature-acknowledgement block added (to match the Sales Code of Conduct), and are there existing signed copies on file for current staff?', 'open', 'knowledge/strategy_roles.json open_questions[5]', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, question = excluded.question, status = excluded.status, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, question, status, _src, _seed, data) values ('di-strategy-roles-q-6-e1f11b', 'STRATE-Q07', 'Strategy & roles', 'low', 'Is there a named incumbent Operations Manager (the job description and workflow documents refer to the role generically; cross-referenced ops-register data names ''Renesh'' as a job-site supervisor — is this the same pe…', 'Is there a named incumbent Operations Manager (the job description and workflow documents refer to the role generically; cross-referenced ops-register data names ''Renesh'' as a job-site supervisor — is this the same person as the Operations Manager)?', 'open', 'knowledge/strategy_roles.json open_questions[6]', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, question = excluded.question, status = excluded.status, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, question, status, _src, _seed, data) values ('di-strategy-roles-q-7-3b608e', 'STRATE-Q08', 'Strategy & roles', 'low', 'Are there other quarters/versions of the ''Key Focus Areas'' document for periods before/after July–Sept 2026 that should also be captured, and did the company hit the R10k/month sales-growth target set for that quarter?', 'Are there other quarters/versions of the ''Key Focus Areas'' document for periods before/after July–Sept 2026 that should also be captured, and did the company hit the R10k/month sales-growth target set for that quarter?', 'open', 'knowledge/strategy_roles.json open_questions[7]', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, question = excluded.question, status = excluded.status, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-training-firefighting-hsrep-d-d1-846bf7', 'D1', 'Training — fire & SHE rep', 'high', 'The group is labelled "Training certificates packs" but it contains no certificates', 'Evidence: Fire Fighting.pdf is a Facilitator/Learner Guide (cover: "FACILITATOR/LEARNER GUIDE", US 12484). HS REP.pdf is a Learner Guide (cover: "LEARNER GUIDE", US ID 259622). No page has a learner name, ID number, training date, result, certificate number, provider accreditation number, signature or stamp.', 'open', null, 'x/Company Documents-20260923T091637Z-1-001/Company Documents/Fire Fighting.pdf | scan page 1 (printed page 1); x/Company Documents-20260923T091637Z-1-001/Company Documents/HS REP.pdf | scan page 1', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-training-firefighting-hsrep-d-d2-76b2d4', 'D2', 'Training — fire & SHE rep', 'medium', 'The Fire Fighting guide is incomplete: printed pages 37-58 are missing', 'Evidence: The contents list Study Unit 5 up to p.37, the Unit Standard at pp.38-51 and the Learner Workbook Section at pp.52-58. The scan ends at printed p.36 (scan 18 = pp.36+35). The assessment and workbook, where learner details and results would be, are not in the file.', 'open', null, 'x/Company Documents-20260923T091637Z-1-001/Company Documents/Fire Fighting.pdf | scan page 2 (printed page 4); x/Company Documents-20260923T091637Z-1-001/Company Documents/Fire Fighting.pdf | scan page 18 (printed page 36)', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-training-firefighting-hsrep-d-d3-aadf0b', 'D3', 'Training — fire & SHE rep', 'medium', 'The HS Rep guide skips content between scan pages 7 and 8', 'Evidence: Scan 7 ends mid-sentence in "5. H&S Representative inspections" ("...must be presented or submitted at the H&S"). Scan 8 starts with section 7 committee text ("The amount of employer representatives may never exceed..."). Section 6 "Incident and Investigation", listed in the course index, is missing entirely.', 'open', null, 'x/Company Documents-20260923T091637Z-1-001/Company Documents/HS REP.pdf | scan page 2; x/Company Documents-20260923T091637Z-1-001/Company Documents/HS REP.pdf | scan page 7; x/Company Documents-20260923T091637Z-1-001/Company Documents/HS REP.pdf | scan page 8', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-training-firefighting-hsrep-d-d4-f259f6', 'D4', 'Training — fire & SHE rep', 'low', 'The OHS Act number differs within the HS Rep guide', 'Evidence: The introduction quotes "Occupational Health and Safety Act - No 85 of 1993". The list of "Preceding Acts" says "OCCUPATIONAL HEALTH AND SAFETY ACT 83 OF 1993", and lists the current Act as a preceding one.', 'open', null, 'x/Company Documents-20260923T091637Z-1-001/Company Documents/HS REP.pdf | scan page 3', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-training-firefighting-hsrep-d-d5-10a08d', 'D5', 'Training — fire & SHE rep', 'low', 'The Fire Fighting guide gives Study Unit 4 two different titles', 'Evidence: Contents: "Study unit 4: Fire Fighting". Unit title page: "STUDY UNIT 4 FIRE FIGHTING EQUIPMENT".', 'open', null, 'x/Company Documents-20260923T091637Z-1-001/Company Documents/Fire Fighting.pdf | scan page 2 (printed page 4); x/Company Documents-20260923T091637Z-1-001/Company Documents/Fire Fighting.pdf | scan page 12 (printed page 24)', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-training-firefighting-hsrep-d-d6-02bac5', 'D6', 'Training — fire & SHE rep', 'medium', 'Parts of the material are not South African and not company-specific, so they cannot be used as the company''s emergency information as they stand', 'Evidence: The ROAST box says "Call 911 to report the fire" (a US number; low resolution). The HS Rep evacuation diagram is a generic example for "BDP MINING, 42 Mineral Road, BOURKE SA 5084" with a ".com.au" safety-maps mark and an unclear "DIAL 9999". The fire classes use Class C = energised electrical equipment. Landscapers Inc has no evacuation diagram or local emergency numbers in these packs.', 'open', null, 'x/Company Documents-20260923T091637Z-1-001/Company Documents/Fire Fighting.pdf | scan page 18 (printed page 36); x/Company Documents-20260923T091637Z-1-001/Company Documents/Fire Fighting.pdf | scan page 5 (printed page 9); x/Company Documents-20260923T091637Z-1-001/Company Documents/HS REP.pdf | scan page 12', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-training-firefighting-hsrep-d-d7-717560', 'D7', 'Training — fire & SHE rep', 'low', 'The fire fighting guide contradicts itself on its audience, and neither audience is landscaping', 'Evidence: The purpose says the skills are needed "in the field of manufacturing and engineering". The target group lists security members, SANDF, SAPS and Correctional Services. The material is part of SASSETA security Skills Program 1 (Book 8).', 'open', null, 'x/Company Documents-20260923T091637Z-1-001/Company Documents/Fire Fighting.pdf | scan page 3 (printed page 5)', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-training-firefighting-hsrep-d-d8-ca9876', 'D8', 'Training — fire & SHE rep', 'low', 'The HS Rep guide has empty headings where content should be', 'Evidence: "Some of the Symbolic Signs for Health and Safety" (scan 9) is followed by blank space; the signs appear on scan 10. "Personal Protective Equipment" (scan 10) has no text; only images follow on scan 11. The only learner activity table (scan 5) is blank.', 'open', null, 'x/Company Documents-20260923T091637Z-1-001/Company Documents/HS REP.pdf | scan page 5; x/Company Documents-20260923T091637Z-1-001/Company Documents/HS REP.pdf | scan page 9; x/Company Documents-20260923T091637Z-1-001/Company Documents/HS REP.pdf | scan page 10; x/Company Documents-20260923T091637Z-1-001/Company Documents/HS REP.pdf | scan page 11', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
insert into public.data_issues (id, code, source_group, severity, title, detail, status, related, _src, _seed, data) values ('di-training-firefighting-hsrep-d-d9-950997', 'D9', 'Training — fire & SHE rep', 'low', 'Cross-reference: the company is below the s17(1) headcount that makes H&S reps compulsory, yet it holds H&S Rep material. This is not an error, but the owner should know.', 'Evidence: s17(1) applies to employers with more than 20 employees (scan 6). Other knowledge files list about 11-14 people: financials.json employees = 14 names including one suspected duplicate spelling; existing_crm_seed TEAM_MEMBERS = 13; September payroll = 11 named people. An inspector can still require reps under s17(6).', 'open', null, 'x/Company Documents-20260923T091637Z-1-001/Company Documents/HS REP.pdf | scan page 6; cross-reference: knowledge/financials.json employees, knowledge/existing_crm_seed.json TEAM_MEMBERS', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, detail = excluded.detail, status = excluded.status, related = excluded.related, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
