insert into public.data_issues (id, code, source_group, severity, title, question, status, _src, _seed, data) values ('di-training-firefighting-hsrep-q-2-61e310', 'TRAINI-Q03', 'Training — fire & SHE rep', 'low', 'Were the formative (open book) and summative (closed book) assessments done, and what were the results? The workbook pages (Fire Fighting pp.52-58) and the HS Rep activities are missing or blank.', 'Were the formative (open book) and summative (closed book) assessments done, and what were the results? The workbook pages (Fire Fighting pp.52-58) and the HS Rep activities are missing or blank.', 'open', 'knowledge/training_firefighting_hsrep.json open_questions[2]', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, question = excluded.question, status = excluded.status, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
