insert into public.data_issues (id, code, source_group, severity, title, question, status, _src, _seed, data) values ('di-training-firefighting-hsrep-q-5-f34e19', 'TRAINI-Q06', 'Training — fire & SHE rep', 'low', 'Will the company set up a formal H&S committee and quarterly meetings, even though with about 11-14 staff it is below the s17(1) threshold of more than 20 employees?', 'Will the company set up a formal H&S committee and quarterly meetings, even though with about 11-14 staff it is below the s17(1) threshold of more than 20 employees?', 'open', 'knowledge/training_firefighting_hsrep.json open_questions[5]', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, question = excluded.question, status = excluded.status, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
