insert into public.data_issues (id, code, source_group, severity, title, question, status, _src, _seed, data) values ('di-training-firefighting-hsrep-q-7-42ef5d', 'TRAINI-Q08', 'Training — fire & SHE rep', 'low', 'What is the evacuation plan and assembly point for the company premises in Mount Edgecombe, and which local emergency numbers should replace "911" and the sample diagram?', 'What is the evacuation plan and assembly point for the company premises in Mount Edgecombe, and which local emergency numbers should replace "911" and the sample diagram?', 'open', 'knowledge/training_firefighting_hsrep.json open_questions[7]', true, '{}'::jsonb) on conflict (id) do update set code = excluded.code, source_group = excluded.source_group, severity = excluded.severity, title = excluded.title, question = excluded.question, status = excluded.status, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.data_issues._seed and public.data_issues.updated_by is not distinct from public.data_issues.created_by;
