insert into public.files (id, name, drive_id, folder_id, mime, size, kind, description, tags, text_index, source_path, linked, version, expires_on, confidential, _src, _seed, vault_path, storage_path, data) values ('file-0a934e309c6ba48d24b2a5b1', 'INV- SG032.pdf', 'drive-finance', 'fld-drive-finance-invoices-invoices-july-6af25c', 'application/pdf', 104325, 'vault', 'Original company document · 1 record in the system came from it.', '["invoices july"]'::jsonb, 'INVOICE Stephen Garreau Corporate Attention: 91 Merrick Hills​ Invoice Date: 23 July 2026 Invoice Number INV- 032 Reference SG Landscapers INC (Pty) Ltd Block 1B Kingfisher Office Park, 4300 Email: accounts@landscapersinc. co.za Mobile: 069 131 5387 https://landscapes-inc.co.za/ Description Quantity Unit Price Discount Amount ZAR Contractual Monthly Maintenance Service 4 R464.31 N/A R1857.25 (Includes Pool service x 4) TOTAL ZAR R1857.25 Due Date:25 Jul - 1 Aug 2026 Additional projects or services are invoiced separately from monthly services and are due within 7 days of completion and by due date indicated. Economical increase effective from 1 March annually. Banking details: Landscapers INC Standard Bank CURRENT ACC 10264092722 Branch: 051001 REF: SG032 Please use your INVOICE No. or Reference indicated on the invoice for payments. Email POP to accounts@landscapersinc.co.za Our workers are provided with PPE and covered by the Workman''s Compensation Fund. All client vehicles should be parked inside a protected garage and away from driveways to reduce risks of damage and provide access for fleet vehicles & loading of garden waste & branches during our time working on site.', 'x/Invoices-20260923T091654Z-1-001/Invoices/INVOICES JULY/INV- SG032.pdf', '[{"collection":"invoices","id":"inv-invoices-july-inv-sg032-032a97"}]'::jsonb, 1, null, false, 'x/Invoices-20260923T091654Z-1-001/Invoices/INVOICES JULY/INV- SG032.pdf', true, 'FINANCE/Invoices/INVOICES JULY/INV- SG032.pdf', 'drive-finance/file-0a934e309c6ba48d2