insert into public.files (id, name, drive_id, folder_id, mime, size, kind, description, tags, text_index, source_path, linked, version, expires_on, confidential, _src, _seed, vault_path, storage_path, data) values ('file-28addd90c607bb759cf55e66', 'INV- LG041.pdf', 'drive-finance', 'fld-drive-finance-invoices-invoices-july-6af25c', 'application/pdf', 94326, 'vault', 'Original company document · 1 record in the system came from it.', '["invoices july"]'::jsonb, 'INVOICE Lutchmee Guruvadu Corporate Attention: 57 Forestclay Invoice Date: 23 July 2026 Invoice Number INV- 041 Reference LG Landscapers INC (Pty) Ltd Block 1B Kingfisher Office Park, 4300 Email: accounts@landscapersinc. co.za Mobile: 069 131 5387 https://landscapes-inc.co.za/ Description Quantity Unit Price Discount Amount ZAR Contractual Monthly Maintenance Service 2 R150.00 N/A R300.00 TOTAL ZAR R300.00 Due Date:25 Jul - 1 Aug 2026 Additional projects or services are invoiced separately from monthly services and are due within 7 days of completion and by due date indicated. Economical increase effective from 1 March annually. Banking details: Landscapers INC Standard Bank CURRENT ACC 10264092722 Branch: 051001 REF: LG041 Please use your INVOICE No. or Reference indicated on the invoice for payments. Email POP to accounts@landscapersinc.co.za Our workers are provided with PPE and covered by the Workman''s Compensation Fund. All client vehicles should be parked inside a protected garage and away from driveways to reduce risks of damage and provide access for fleet vehicles & loading of garden waste & branches during our time working on site.', 'x/Invoices-20260923T091654Z-1-001/Invoices/INVOICES JULY/INV- LG041.pdf', '[{"collection":"invoices","id":"inv-invoices-july-inv-lg041-5d2551"}]'::jsonb, 1, null, false, 'x/Invoices-20260923T091654Z-1-001/Invoices/INVOICES JULY/INV- LG041.pdf', true, 'FINANCE/Invoices/INVOICES JULY/INV- LG041.pdf', 'drive-finance/file-28addd90c607bb759cf55e66/INV- LG041.pdf', '{"sha25