insert into public.files (id, name, drive_id, folder_id, mime, size, kind, description, tags, text_index, source_path, linked, version, expires_on, confidential, _src, _seed, vault_path, storage_path, data) values ('file-4bd3833f5ec7bf586674f382', 'WARNING FORM.pdf', 'drive-sops', 'fld-drive-sops-h-s-forms-2f6d5f', 'application/pdf', 231585, 'vault', 'Original company document · 1 record in the system came from it.', '["hs forms checklists loa"]'::jsonb, 'WARNING FORM REFERENCE: LI-FORM-002 REVISION: 00 EFFECTIVE DATE: 02-01-2026 REVISION DATE: 02-01-2027 Verbal / Written / Final (Circle Appropriate) COPIES TO: (A) WORKERS PERSONNEL SECTION (B) WORKER NAME: COMPANY NUMBER: BRANCH: NAME OF WORKERS RESPRESENTATIVE: DETAILS OF CHARGES, COMPLAINT (S) OR UNSATIFACTORY BEHAVIOUR / PERFORMANCE: VALID FOR : 6 MONTHS / 12 MONTHS / 18 MONTHS / 24 MONTHS. WORKER’S SIGNATURE: WARNING ISSUED BY: DESIGNATION (In the presence of Worker’s Representative) SIGNED: DATE: COMMENTS: THIS WARNING IS TO BE KEPT IN THE EMPLOYEES PERSONNEL RECORDS IN THE EVENT OF FURTHER COMPLAINTS OR UNSATISFACTORY BEHAVIOUR/ PERFORMANCE TO BE USED IN FUTURE DISCIPLINARY ACTION.', 'x/H&S-20260923T091746Z-1-001/H&S/Forms/WARNING FORM.pdf', '[{"collection":"forms","id":"form-li-form-002-c5dde3"}]'::jsonb, 1, null, false, 'x/H&S-20260923T091746Z-1-001/H&S/Forms/WARNING FORM.pdf', true, 'SOP''S & TEMPLATES/H&S/Forms/WARNING FORM.pdf', 'drive-sops/file-4bd3833f5ec7bf586674f382/WARNING FORM.pdf', '{"sha256":"4bd3833f5ec7bf586674f3821b60c8ffa92b38c339f82aad8b598c1622a862f0","also_at":["x/H&S-20260923T091746Z-1-001/H&S/Forms/WARNING FORM.pdf"]}'::jsonb) on conflict (id) do update set name = excluded.name, drive_id = excluded.drive_id, folder_id = excluded.folder_id, mime = excluded.mime, size = excluded.size, kind = excluded.kind, description = excluded.description, tags = excluded.tags, text_index = excluded.text_index, source_path = excluded.source_path, linked = excluded.linked, version = excluded.version, expi