insert into public.forms (id, title, category, description, questions, accepting, _src, _seed, data) values ('form-checklist-12-month-revenue-growth-plan-dd0c1f', '12-Month Revenue Growth Plan — checklist', 'checklist', 'Built from “12-Month Revenue Growth Plan”. Tick items as they are done; success measures are shown per section.', '[{"id":"s0","type":"section","label":"Quarter 1 actions","help":"Generate more qualified leads and improve conversion rates."},{"id":"s0q0","type":"checkbox","label":"Improve online presence.","required":false},{"id":"s0q1","type":"checkbox","label":"Launch Google Ads.","required":false},{"id":"s0q2","type":"checkbox","label":"Optimise Google Business Profile.","required":false},{"id":"s0q3","type":"checkbox","label":"Implement quotation follow-up system.","required":false},{"id":"s0q4","type":"checkbox","label":"Introduce referral programme.","required":false},{"id":"s1","type":"section","label":"Quarter 2 actions","help":"Grow recurring revenue and commercial work."},{"id":"s1q0","type":"checkbox","label":"Target commercial clients.","required":false},{"id":"s1q1","type":"checkbox","label":"Build partnerships with estate agents.","required":false},{"id":"s1q2","type":"checkbox","label":"Launch upselling programme.","required":false},{"id":"s1q3","type":"checkbox","label":"Increase recurring maintenance contracts.","required":false},{"id":"s2","type":"section","label":"Quarter 3 actions","help":"Improve profitability while maintaining service quality."},{"id":"s2q0","type":"checkbox","label":"Expand marketing campaigns.","required":false},{"id":"s2q1","type":"checkbox","label":"Increase customer retention initiatives.","required":false},{"id":"s2q2","type":"checkbox","label":"Review service pricing.","required":false},{"id":"s2q3","type":"checkbox","label":"Increase average job value.","required":false},{"id":"s3","type":"section","label":"Quarter 4 actions","help":"Achieve annual revenue target and prepare for the next growth phase."},{"id":"s3q0","type":"checkbox","label":"Review annual performance.","required":false},{"id":"s3q1","type":"checkbox","label":"Double down on highest-performing marketing channels.","required":false},{"id":"s3q2","type":"checkbox","label":"Plan next year''s growth strategy.","required":false},{"id":"s3q3","type":"checkbox","label":"Prepare staffing and equipment for future expansion.","required":false}]'::jsonb, true, 'x/Landscapers Inc 12 month plan.docx', true, '{}'::jsonb) on conflict (id) do update set title = excluded.title, category = excluded.category, description = excluded.description, questions = excluded.questions, accepting = excluded.accepting, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.forms._seed and public.forms.updated_by is not distinct from public.forms.created_by;
