insert into public.forms (id, title, category, description, questions, accepting, _src, _seed, data) values ('form-checklist-operations-department-code-of--3797d2', 'Operations Department Code of Conduct — checklist', 'checklist', 'Built from “Operations Department Code of Conduct”. Tick items as they are done; success measures are shown per section.', '[{"id":"s0","type":"section","label":"1. Professionalism","help":null},{"id":"s0q0","type":"checkbox","label":"Conduct yourself professionally at all times.","required":false},{"id":"s0q1","type":"checkbox","label":"Treat clients, colleagues and suppliers with respect.","required":false},{"id":"s0q2","type":"checkbox","label":"Represent the company positively on and off client sites.","required":false},{"id":"s0q3","type":"checkbox","label":"Maintain a positive attitude and strong work ethic.","required":false},{"id":"s1","type":"section","label":"2. Integrity","help":null},{"id":"s1q0","type":"checkbox","label":"Be honest in all reporting and communication.","required":false},{"id":"s1q1","type":"checkbox","label":"Never falsify records, timesheets or company documents.","required":false},{"id":"s1q2","type":"checkbox","label":"Report mistakes immediately so they can be resolved.","required":false},{"id":"s1q3","type":"checkbox","label":"Protect company assets and confidential information.","required":false},{"id":"s2","type":"section","label":"3. Punctuality & Attendance","help":null},{"id":"s2q0","type":"checkbox","label":"Arrive at work on time and ready to begin the day.","required":false},{"id":"s2q1","type":"checkbox","label":"Notify your manager as early as possible if you are unable to attend work.","required":false},{"id":"s2q2","type":"checkbox","label":"Complete assigned tasks within agreed timeframes.","required":false},{"id":"s2q3","type":"checkbox","label":"Attend all required meetings and briefings.","required":false},{"id":"s3","type":"section","label":"4. Health & Safety","help":null},{"id":"s3q0","