insert into public.forms (id, title, category, description, questions, accepting, _src, _seed, data) values ('form-checklist-operations-workflow-1fff5e', 'Operations Workflow — checklist', 'checklist', 'Built from “Operations Workflow”. Tick items as they are done; success measures are shown per section.', '[{"id":"s0","type":"section","label":"Step 1: Lead Generated","help":null},{"id":"s0q0","type":"checkbox","label":"Client enquiry is received.","required":false},{"id":"s0q1","type":"checkbox","label":"Lead is recorded in the Lead Register or CRM.","required":false},{"id":"s0q2","type":"checkbox","label":"The sales representative contacts the client.","required":false},{"id":"s0q3","type":"checkbox","label":"Site visit is scheduled if required.","required":false},{"id":"s1","type":"section","label":"Step 2: Quotation","help":null},{"id":"s1q0","type":"checkbox","label":"Site inspection is completed.","required":false},{"id":"s1q1","type":"checkbox","label":"Scope of work is determined.","required":false},{"id":"s1q2","type":"checkbox","label":"A quote is prepared and sent to the client.","required":false},{"id":"s1q3","type":"checkbox","label":"The quote is recorded in the Quote Register.","required":false},{"id":"s1q4","type":"checkbox","label":"Follow-up is conducted until the client makes a decision.","required":false},{"id":"s2","type":"section","label":"Step 3: Quote Accepted","help":null},{"id":"s2q0","type":"checkbox","label":"Client accepts the quotation.","required":false},{"id":"s2q1","type":"checkbox","label":"The job is approved for scheduling.","required":false},{"id":"s2q2","type":"checkbox","label":"Relevant documentation is received if required.","required":false},{"id":"s3","type":"section","label":"Step 4: Job Planning","help":null},{"id":"s3q0","type":"checkbox","label":"Job is entered into the Job Register.","required":false},{"id":"s3q1","type":"checkbox","label":"The job date is scheduled.","required":false},{"id":"s3q2","type":"checkbox","l