insert into public.forms (id, title, category, description, questions, accepting, _src, _seed, data) values ('form-checklist-weekly-operations-meeting-agen-ca0851', 'Weekly Operations Meeting Agenda — checklist', 'checklist', 'Built from “Weekly Operations Meeting Agenda”. Tick items as they are done; success measures are shown per section.', '[{"id":"s0","type":"section","label":"1. Opening","help":null},{"id":"s0q0","type":"checkbox","label":"Welcome","required":false},{"id":"s0q1","type":"checkbox","label":"Confirm attendance","required":false},{"id":"s0q2","type":"checkbox","label":"Review previous meeting action items","required":false},{"id":"s1","type":"section","label":"2. Safety","help":null},{"id":"s1q0","type":"checkbox","label":"Incidents or accidents","required":false},{"id":"s1q1","type":"checkbox","label":"Near misses","required":false},{"id":"s1q2","type":"checkbox","label":"Safety concerns","required":false},{"id":"s1q3","type":"checkbox","label":"PPE compliance","required":false},{"id":"s1q4","type":"checkbox","label":"Corrective actions","required":false},{"id":"s2","type":"section","label":"3. Operations Performance","help":null},{"id":"s2q0","type":"checkbox","label":"Jobs completed","required":false},{"id":"s2q1","type":"checkbox","label":"Jobs in progress","required":false},{"id":"s2q2","type":"checkbox","label":"Delayed jobs","required":false},{"id":"s2q3","type":"checkbox","label":"Upcoming projects","required":false},{"id":"s2q4","type":"checkbox","label":"Productivity review","required":false},{"id":"s3","type":"section","label":"4. Quality","help":null},{"id":"s3q0","type":"checkbox","label":"Client feedback","required":false},{"id":"s3q1","type":"checkbox","label":"Site inspections","required":false},{"id":"s3q2","type":"checkbox","label":"Rework required","required":false},{"id":"s3q3","type":"checkbox","label":"Quality improvements","required":false},{"id":"s4","type":"section","label":"5. Staff","help":null},{"id":"s4q0","type":"check