insert into public.forms (id, title, category, doc_code, description, questions, accepting, require_signature, source_path, _src, _seed, data) values ('form-hse-chk001-dfea18', 'Pressure Hose Monthly Inspection Checklist', 'inspection', 'HSE-CHK001', 'Revision 00 · effective 2026-01-02 · review 2027-01-02. Risk Rate Deviation Key value 1-5 (see risk_rating_key), one entry per month. Includes the Pressure hose register (Asset #, Description of hose type, Location, Maintenance program number, Responsibility full name).', '[{"id":"q0","type":"section","label":"Risk rate deviation key","help":"1 = Legally and Company Compliant · 2 = Light Risk - 1 Month Action · 3 = Medium Risk - 1 Week Action · 4 = High Risk - 24 Hour Action · 5 = Critical Risk - Immediate Action"},{"id":"g1","type":"grid","label":"Pressure Hose Monthly Inspection Checklist","rows":["All hoses identified","All identification numbers legible","All hoses listed on register","All hoses on maintenance program","Storage identified","Storage demarcated","Storage identification legible/visible","No visible damage present","Thread of nozzle is in good condition","The nozzle does not leak","Nozzle firmly attached to the hose","No visible damage to the pipe present","The hose is safely attached to nozzle"],"columns":["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],"scale":{"options":["1","2","3","4","5"]},"help":"Risk Rate Deviation Key value 1-5 (see risk_rating_key), one entry per month"},{"id":"f1","type":"date","label":"Inspection Date"},{"id":"f2","type":"text","label":"HS Representative Initials"},{"id":"f3","type":"date","label":"Audited Date"},{"id":"f4","type":"text","label":"Auditor Initials"},{"id":"dmg","type":"paragraph","label":"Damaged / defective items and action taken","help":"DAMAGED ITEMS instruction block: items FOR REPAIR must be clearly identified with an A4 notice in red ink \"OUT OF COMMISSION\" signage in a plastic sleeve or laminated and securely attached to the