insert into public.settings (id, key, description, value, _src, _seed, data) values ('set-company-profile', 'company_profile', 'Company details used on quotes, invoices and letterheads.', '{"trading_name":"Landscapers Inc","legal_name":"JKN Property Consortium (Pty) Ltd","reg_no":"2024/786147/07","cipc_enterprise_no":"K2024786147","address":"Block 1B Kingfisher Office Park, 28-30 Siphosethu Road, Mount Edgecombe, Kwa-Zulu Natal, 4300","postal_code":"4300","phone":"069 131 5387","email":"Sales@landscapersinc.co.za","accounts_email":null,"website":null,"whatsapp":"+27 70 695 7485","directors":["Jared Emmanuel Naidoo"],"vat_registered":false,"vat_number":null,"tax_ref":"9211719274","bbbee_level":"1","coida_no":null,"financial_year_end":"February","tagline":"Structured. Reliable. Compliant. Professional Estate Landscaping Solutions.","positioning":"Professional Estate Landscaping & Grounds Maintenance; Estate & Office Park Landscaping Services","invoice_prefix":"LSI-","next_invoice_no":1001,"quote_prefix":"QT-","next_quote_no":1001,"default_due_days":7,"quote_valid_days":30,"deposit_pct":50,"invoice_terms":"Additional projects or services are invoiced separately from monthly services and are due within 7 days of completion and by due date indicated. Economical increase effective from 1 March annually.","invoice_footer_notes":"Please use your invoice number as the payment reference and send proof of payment to Sales@landscapersinc.co.za or WhatsApp 070 695 7485.","quote_terms":"This quotation is valid for 30 days. A 50% deposit confirms the booking; the balance is due on completion. Any work not listed is quoted separately."}'::jsonb, 'knowledge/company_compliance.json company_facts', true, '{}'::jsonb) on conflict (id) do update set key = excluded.key, description = excluded.description, value = excluded.value, _src = excluded._src, _seed = excluded._seed, data = excluded.data where public.settings._seed and public.settings.updated_by is not distinct from public.setting